/**
 * 設定資料パネルの書き込みと吹き出し（画面の自動テスト、設計書6.5・6.93.7・6.113。実機確認リストの
 * 仕分け 2026-10-12 の束 E2 を移したもの。作者の裁定「仕分けて機械の分から減らす」）。
 *
 * 1. 場所に「位置関係（1行に1つ）」の欄があり、書き足して保存すると、足した行が**作者の確定**
 *    （`authorLocked: true`）としてファイルに残る。触らなかった行（抽出が入れた関係）は話数と根拠ごと
 *    そのまま残り、記録は作者の確定（`autoGenerated: false`）になる（実機確認リスト 25 行）。
 *    「次の抽出で変わらない」は AI を呼ばないと起こせないので、ここでは見ない
 *    （読み方と固定の印は単体テスト `core/settingsEdit` 系が見ている）
 * 2. 人物の「変化かもしれない」の行に並ぶ値ごとの札（「…」は誤り（落とす））のうち、長い値の札は
 *    頭だけを見せ、**指を載せたときの説明（`title`）に全文が入っている**（実機確認リスト 418 行。
 *    札の並びは作者が写真で確かめ済み。残っていたのは吹き出しの全文）。吹き出しそのものは
 *    ブラウザが描くもので DOM に出ないので、確かめるのは `title` の字までと、札が何にも
 *    覆われず指を載せられること
 *
 * 記録は製品が読む形で、VS Code を起こす前に置く。**AI は呼ばない。**
 */
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import type { Frame } from "playwright-core";
import { expect, test } from "vitest";
import { emptyCharacter, type Character } from "../../src/models/character";
import { emptyLocation, locationFileName, type Location, type LocationRelation } from "../../src/models/location";
import { DEFAULT_SETTINGS_DIR } from "../../src/models/types";
import { readJsonWhenPresent } from "./support/fileSettle";
import { runCommand } from "./support/quickInput";
import { defaultCharactersFolder, settingsPanelFrame, settingsListRows, writeCharactersTo } from "./support/settingsFixture";
import { withVsCode, type E2ESession } from "./support/vscodeApp";
import { waitUntil } from "./support/wait";

const EPISODE = { name: "001_はじまり.txt", text: "港の北に学校がある。\n" };

/** 設定資料パネルを開く（コマンドパレットから。作者と同じ道） */
async function openSettingsPanel(session: E2ESession): Promise<Frame> {
  await runCommand(session.page, "設定資料集閲覧");
  let panel: Frame | undefined;
  await waitUntil(async () => (panel = await settingsPanelFrame(session)) !== undefined, "設定資料パネルが開く", 30_000);
  if (!panel) throw new Error("設定資料パネルの面が見つかりません");
  return panel;
}

/** 左の一覧で `name` の行を選ぶ（`kind` のタブへ切り替えてから） */
async function selectRecord(frame: Frame, kind: string, name: string): Promise<void> {
  const tab = frame.locator(`#tabs button[data-kind="${kind}"]`);
  await waitUntil(async () => (await tab.count()) > 0, `種類「${kind}」のタブが出る`, 15_000);
  await tab.first().click();
  await waitUntil(
    async () => (await frame.locator("#list .item", { hasText: name }).count()) > 0,
    `一覧に「${name}」が出る`,
    20_000
  ).catch(async (error: unknown) => {
    throw new Error(`${String(error)}（一覧の行：${JSON.stringify(await settingsListRows(frame))}）`);
  });
  await frame.locator("#list .item", { hasText: name }).first().click();
}

/** 保存は「退避 → 新規作成」で書かれる。読めるまで少し待って読む（`support/fileSettle.ts`） */
const readJson = readJsonWhenPresent;

/* ── 1. 場所の位置関係を書き足して保存する ── */

function rel(kind: LocationRelation["kind"], target: string, value: string | null, extra: Partial<LocationRelation> = {}): LocationRelation {
  return { kind, target, targetId: null, value, chapters: [], evidence: null, authorLocked: false, ...extra };
}

/** 港と学校。学校には、抽出が入れた形の関係（話数と根拠つき）が1本ある */
function places(): Location[] {
  return [
    { ...emptyLocation("loc_001", "港"), appearedChapters: [1] },
    {
      ...emptyLocation("loc_002", "学校"),
      appearedChapters: [1],
      relations: [rel("direction", "港", "北", { targetId: "loc_001", chapters: [1], evidence: "港の北に学校がある。" })],
    },
  ];
}

function locationsFolder(workFolder: string): string {
  return path.join(workFolder, DEFAULT_SETTINGS_DIR, "locations");
}

test("場所の「位置関係（1行に1つ）」に1行書き足して保存すると、足した行は作者の確定で残り、抽出が入れた行は話数と根拠ごと残る", async () => {
  const school = places()[1];
  await withVsCode(
    "場所の位置関係の保存",
    [EPISODE],
    async (session) => {
      const file = path.join(locationsFolder(session.workFolder), locationFileName(school));
      const frame = await openSettingsPanel(session);
      await selectRecord(frame, "location", "学校");

      const field = frame.locator("#detail .field", { hasText: "位置関係（1行に1つ）" }).first();
      await field.waitFor({ timeout: 15_000 }).catch((error: unknown) => {
        throw new Error(`場所の詳細に「位置関係（1行に1つ）」の欄が出ません：${String(error).split("\n")[0]}`);
      });
      const textarea = field.locator("textarea");
      expect(await textarea.inputValue(), "位置関係の欄に、抽出が入れた関係が出ていません").toBe("港の北");
      // 欄の説明に「直した行は抽出で変わらない」ことが書かれている（作者が何を確定したのか分かるように）
      expect((await field.innerText()).replace(/\s+/g, " "), "位置関係の欄の説明").toContain("AIの抽出で変わりません");

      await textarea.fill("港の北\n港から徒歩10分");
      await frame.locator("#detail .saverow button.action", { hasText: "保存" }).click();

      await waitUntil(
        async () => ((await readJson<Location>(file)).relations ?? []).length === 2,
        "書き足した位置関係がファイルに入る",
        20_000
      ).catch(async (error: unknown) => {
        const status = (await frame.locator("#status").textContent().catch(() => "")) ?? "";
        throw new Error(`${String(error)}（いまのファイル：${await readFile(file, "utf8").catch(() => "読めない")}／パネルの知らせ：${status}）`);
      });
      const saved = await readJson<Location>(file);
      const relations = saved.relations ?? [];
      const added = relations.find((entry) => entry.kind === "distance");
      expect(added, `足した行が読めていません：${JSON.stringify(relations)}`).toBeDefined();
      expect(added?.target).toBe("港");
      expect(added?.value).toBe("徒歩10分");
      expect(added?.authorLocked, "足した行が作者の確定になっていません").toBe(true);
      expect(added?.evidence, "作者が書いた行に根拠が付いています").toBeNull();
      expect(added?.targetId, "相手の場所の ID が引けていません").toBe("loc_001");
      // 触らなかった行は、抽出が入れたまま（話数・根拠・固定していない印）
      const kept = relations.find((entry) => entry.kind === "direction");
      expect(kept, `元の行が消えました：${JSON.stringify(relations)}`).toEqual(school.relations?.[0]);
      // 記録そのものも作者の確定になる
      expect(saved.autoGenerated, "保存したのに記録が自動生成のままです").toBe(false);
    },
    {
      prepareWork: async ({ workFolder }) => {
        const folder = locationsFolder(workFolder);
        await mkdir(folder, { recursive: true });
        for (const location of places()) {
          await writeFile(path.join(folder, locationFileName(location)), `${JSON.stringify(location, null, 2)}\n`, "utf8");
        }
      },
    }
  );
});

/* ── 2. 「変化かもしれない」の長い値の札 ── */

const LONG_VALUE = "港町の外れで古書店を営みながら、夜は灯台守として沖の船を見張っている";
const SHORT_VALUE = "古書店の店主";

/** 紹介（summary）に食い違いを1件持つ人物。片方の値は札に載る長さ（12字）を超える */
function personWithConflict(): Character {
  return {
    ...emptyCharacter("char_001", "白瀬灯"),
    appearedChapters: [1, 2, 3, 4, 5],
    summary: SHORT_VALUE,
    conflicts: [
      {
        field: "summary",
        values: [SHORT_VALUE, LONG_VALUE],
        chapters: [2, 5],
        note: null,
        observations: [
          { value: SHORT_VALUE, chapters: [2] },
          { value: LONG_VALUE, chapters: [5] },
        ],
      },
    ],
  };
}

test("「変化かもしれない」の行の長い値の札は頭だけを見せ、指を載せたときの説明（title）に全文が入っている", async () => {
  await withVsCode(
    "変化かもしれないの札の説明",
    [EPISODE],
    async (session) => {
      const frame = await openSettingsPanel(session);
      await selectRecord(frame, "character", "白瀬灯");

      const line = frame.locator("#detail .readonly", { hasText: "変化かもしれない（summary）" }).first();
      await line.waitFor({ timeout: 15_000 }).catch(async (error: unknown) => {
        const lines = await frame.evaluate(() =>
          Array.from(document.querySelectorAll("#detail .readonly")).map((row) => (row as HTMLElement).innerText.replace(/\s+/g, " ").trim())
        );
        throw new Error(`「変化かもしれない（summary）」の行が出ません：${String(error).split("\n")[0]}（参考の行：${JSON.stringify(lines)}）`);
      });
      const chips = await line.locator("button.value-action").evaluateAll((buttons) =>
        buttons.map((button) => ({ text: (button.textContent ?? "").trim(), title: button.getAttribute("title") ?? "" }))
      );
      expect(chips.length, `値ごとの札：${JSON.stringify(chips)}`).toBe(2);

      const long = chips.find((chip) => chip.title.includes(LONG_VALUE));
      expect(long, `長い値の全文が、どの札の説明（title）にもありません：${JSON.stringify(chips)}`).toBeDefined();
      // 札の字は頭だけ（12字＋「…」）。全文は札の字には出ない
      expect(long?.text, `長い値の札の字：${long?.text}`).toContain(`${[...LONG_VALUE].slice(0, 12).join("")}…`);
      expect(long?.text).not.toContain(LONG_VALUE);
      // 短い値は札にそのまま出る
      const short = chips.find((chip) => chip.title.includes(SHORT_VALUE) && !chip.title.includes(LONG_VALUE));
      expect(short?.text, `短い値の札：${JSON.stringify(chips)}`).toContain(`「${SHORT_VALUE}」`);

      // 長い値の札は何にも覆われておらず、指を載せられる（載せた所でいちばん上にあるのがその札）
      const longButton = line.locator("button.value-action", { hasText: [...LONG_VALUE].slice(0, 12).join("") }).first();
      await longButton.scrollIntoViewIfNeeded();
      await longButton.hover();
      const onTop = await longButton.evaluate((button) => {
        const box = button.getBoundingClientRect();
        const top = document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2);
        return top === button || button.contains(top) ? "" : `${top?.tagName ?? "なし"}.${String(top?.className ?? "")}`;
      });
      expect(onTop, `長い値の札の上に別のものが重なっています：${onTop}`).toBe("");
    },
    {
      prepareWork: async ({ workFolder }) => {
        await writeCharactersTo(defaultCharactersFolder(workFolder), [personWithConflict()]);
      },
    }
  );
});
